def str_to_tuple(s):
    parts = s.split()
    result = []
    for part in parts:
        try:
            num = int(part)
            result.append(num)
        except ValueError:
            continue
    return tuple(result)

def next_power_of_2(n: int) -> int:
    if n <= 1:
        return 1
    power = 1
    while power < n:
        power <<= 1
    return power

